JOINT_HYPERPARAM_OPT_SPECS += [
    {'label': 'Fresh-check method', 'type': 'str', 'default': 'fresh_refit', 'opt_key': 'gate_mode',
     'choices': ['fresh_refit', 'bbc'],
     'help': ("How the search's winner is checked against not tuning at all. 'fresh_refit' "
              "(default) refits the models on fresh resamples of the training rows (60-90 extra "
              "model fits per task). 'bbc' needs NO extra model fits: it repeats the "
              "whole 'pick the best library column per model' procedure on bootstrap resamples "
              "of the scoring rows and checks that the winner's advantage survives on the rows "
              "each resample left out (Tsamardinos et al., 2018). Needs a library search "
              "('block_coordinate', 'parallel_library' or 'async_library'); otherwise the "
              "fresh refit is used and the run log says so.")},
    {'label': 'Bootstrap resamples for the BBC check', 'type': 'int', 'default': 200,
     'opt_key': 'bbc_bootstraps',
     'help': ("Only applies when Fresh-check method is 'bbc' or Library selection rule is 'bbc'. "
              "How many bootstrap resamples of the scoring rows are used. More is steadier and "
              "costs only closed-form solves (no model fits). At least 20 are needed.")},
    {'label': 'Use a 1-row test frame for search fits', 'type': 'bool', 'default': False,
     'opt_key': 'search_test_stub',
     'help': ("Search-time shortcut for rrBLUP, GBLUP, BayesB and RKHS: the search fits are "
              "given one test row instead of the whole test set, because the search never "
              "reads the test predictions, and these models' cost grows with the number of rows "
              "they are handed. The final fits always get the full test set. Checked once per "
              "task and model against a normal fit (correlation >= 0.995), and switched off for "
              "that model with a run-log note if it fails. Not used with BLUE weighting or when "
              "the library dump is on.")},
    {'label': 'Search engine for rrBLUP / RKHS', 'type': 'str', 'default': 'bglr',
     'opt_key': 'search_engine', 'choices': ['bglr', 'exact_kernel'],
     'help': ("'bglr' (default) runs the real BGLR model for every search fit. 'exact_kernel' "
              "answers rrBLUP and RKHS SEARCH fits with the closed-form posterior of "
              "the same kernel regression (milliseconds instead of an MCMC run); the final "
              "confirmatory fit is always the real BGLR model. Checked once per task against "
              "the real BGLR seed column (correlation >= 0.98) and switched off for a model "
              "that fails the check. Not used with BLUE weighting.")},
    {'label': 'Library columns per tunable dimension', 'type': 'int', 'default': 6,
     'opt_key': 'library_evals_per_dim',
     'help': ("Only applies when Search strategy is 'async_library'. Each model fits about "
              "1 + this number x (its tunable fields) library columns, at least 4 and at most "
              "30 (times the CV folds when scoring on 'cv_train_valid').")},
    {'label': 'Noise-aware search surrogate', 'type': 'bool', 'default': False,
     'opt_key': 'noise_aware_surrogate',
     'help': ("The search's Gaussian-process model is told that each score is noisy, "
              "and the winner is the point the model believes is best rather than the single "
              "highest observed score, which reduces choosing a lucky draw. Off (default) keeps "
              "the previous behaviour exactly. Not yet shown to help on real data.")},
    {'label': 'Library selection rule', 'type': 'str', 'default': 'greedy',
     'opt_key': 'selection_rule', 'choices': ['greedy', 'bbc'],
     'help': ("How the library search picks one column per model. 'greedy' (default) takes the "
              "combination that scores best on all rows. 'bbc' instead takes the "
              "combination with the best average score on the rows left out of bootstrap "
              "resamples (zero extra model fits), which is less prone to a combination that only "
              "looks good on these rows. Needs a library search strategy.")},
]
