# ver4-68 (R4): which widgets belong to which mode. The keys the two-phase mode never reads
# (pipeline_utils._ITER_ENS_TWO_PHASE_IGNORED) are greyed out in it; the keys that exist only for
# it (the ver4-68 / ver4-69 additions except `mode`) are greyed out in the subset mode.
ITER_ENS_SUBSET_ONLY_KEYS = frozenset(_pipeline_utils._ITER_ENS_TWO_PHASE_IGNORED)
ITER_ENS_TWO_PHASE_ONLY_KEYS = frozenset(_pipeline_utils._ITER_ENS_APPENDED_KEYS) - {'mode'}
# the three keys a tier bundles (pipeline_utils._ITER_ENS_TIERS)
ITER_ENS_TIER_KEYS = ('weight_rule', 'p1_rounds', 'p2_rounds')


def _iter_ens_default(key):
    """The default of one Iterative-ensemble setting (pipeline_utils is the single authority)."""
    return _pipeline_utils._ITER_ENS_DEFAULTS[key]


def _iter_ens_visible(field):
    """True when a field's `when` condition (another widget's value) holds, or it has none."""
    when = field.get('when')
    if when is None:
        return True
    other, required = when
    return st.session_state.get(f'iter_ens_{other}', _iter_ens_default(other)) == required


def _iter_ens_field_disabled(field):
    """ver4-68 (R4): True when the current mode never reads this field (it is then greyed out,
    not hidden, so the user sees which settings the other mode owns)."""
    mode = st.session_state.get('iter_ens_mode', _iter_ens_default('mode'))
    if mode == 'two_phase':
        return field['key'] in ITER_ENS_SUBSET_ONLY_KEYS
    return field['key'] in ITER_ENS_TWO_PHASE_ONLY_KEYS


def _render_iter_ens_field(field):
    """Draw one field as a name-keyed widget (`iter_ens_<key>`) with its pipeline default."""
    key, label, kind = field['key'], field['label'], field['kind']
    wkey, default, help_text = f'iter_ens_{key}', _iter_ens_default(key), field.get('help')
    off = _iter_ens_field_disabled(field)
    if kind == 'bool':
        st.checkbox(label, value=default, key=wkey, help=help_text, disabled=off)
    elif kind == 'int':
        st.number_input(label, min_value=field.get('min'), max_value=field.get('max'),
                        value=int(default), step=1, key=wkey, help=help_text, disabled=off)
    elif kind == 'float':
        st.number_input(label, min_value=float(field['min']),
                        max_value=None if field.get('max') is None else float(field['max']),
                        value=float(default), step=float(field['step']),
                        format='%.4f' if field['step'] < 0.01 else '%.2f', key=wkey,
                        help=help_text, disabled=off)
    elif kind == 'slider':
        st.slider(label, min_value=float(field['min']), max_value=float(field['max']),
                  value=float(default), step=float(field['step']), key=wkey, help=help_text,
                  disabled=off)
    elif kind == 'select':
        st.selectbox(label, options=field['options'], index=field['options'].index(default),
                     format_func=lambda v, _l=field['labels']: _l[v], key=wkey, help=help_text,
                     disabled=off)
    else:
        raise ValueError(f"ITER_ENS_FIELDS: unknown kind {kind!r} for field {key!r}")


def resolve_iter_ens():
    """Collect the Iterative-ensemble widgets into the ITERATIVE_ENSEMBLE dict (every key of
    pipeline_utils._ITER_ENS_DEFAULTS, validated types). A widget that is not on screen (its
    `when` condition is false, or the panel was never opened) yields the pipeline default."""
    out = {}
    for field in ITER_ENS_FIELDS:
        key, kind = field['key'], field['kind']
        default = _iter_ens_default(key)
        value = st.session_state.get(f'iter_ens_{key}', default)
        if kind == 'bool':
            out[key] = bool(value)
        elif kind == 'int':
            out[key] = int(value)
        elif kind in ('float', 'slider'):
            out[key] = float(value)
        else:
            out[key] = value if value in field['options'] else default
    return out


def _iter_ens_apply_tier():
    """ver4-68 (R4): `on_change` of the tier select - write the chosen tier's key bundle
    (pipeline_utils._ITER_ENS_TIERS, single authority) into the ordinary name-keyed widgets.
    'Custom' changes nothing. A widget callback runs before the script reruns, so writing the
    other widgets' session-state keys here is allowed."""
    label = st.session_state.get('iter_ens_tier')
    for name, tier_label in ITER_ENS_TIER_LABELS.items():
        if tier_label == label and name in _pipeline_utils._ITER_ENS_TIERS:
            for key, value in _pipeline_utils._ITER_ENS_TIERS[name].items():
                st.session_state[f'iter_ens_{key}'] = value


def _render_iter_ens_tier_select():
    """ver4-68 (R4): the tier select of the two-phase mode. The tier is DERIVED, never stored
    (I1/I11): before the widget is drawn its value is recomputed from the current bundle widgets
    with ``pipeline_utils.iter_ens_tier_of`` - so editing a bundled widget turns it to 'Custom',
    and a loaded config shows the tier its keys correspond to."""
    derived = _pipeline_utils.iter_ens_tier_of(resolve_iter_ens())
    st.session_state['iter_ens_tier'] = ITER_ENS_TIER_LABELS[derived]
    st.selectbox('Cost tier', options=list(ITER_ENS_TIER_LABELS.values()), key='iter_ens_tier',
                 on_change=_iter_ens_apply_tier,
                 help='Lite: equal pool, no out-of-fold fits (3 refits per model). Standard: '
                      'out-of-fold model weights + 1 distillation round + 3 diversity rounds. '
                      'Thorough: 3 distillation rounds. Editing a setting below switches to '
                      'Custom.')


def render_iter_ens_panel(selected_models):
    """Tab 4 panel for the opt-in Iterative ensemble: description, the mode select, (two-phase)
    the cost-tier select, the basic fields, an 'Advanced' expander, a warning when fewer than 2
    models are selected and the expected extra-fit count (pipeline_utils.iter_ens_fit_estimate -
    bio-prior models are never refit) with the number of fit waves in the two-phase mode."""
    models = [m for m in (selected_models or []) if m != 'ensemble']
    mode_field = next(f for f in ITER_ENS_FIELDS if f['key'] == 'mode')
    _render_iter_ens_field(mode_field)
    two_phase = st.session_state.get('iter_ens_mode', _iter_ens_default('mode')) == 'two_phase'
    st.caption(ITER_ENS_TWO_PHASE_DESCRIPTION if two_phase else ITER_ENS_DESCRIPTION)
    if len(models) < 2:
        st.warning("The iterative ensemble needs at least 2 selected models - with fewer it "
                   "produces no row.")
    if two_phase:
        _render_iter_ens_tier_select()
    for field in ITER_ENS_FIELDS:
        if field['key'] != 'mode' and not field['advanced'] and _iter_ens_visible(field):
            _render_iter_ens_field(field)
    with st.expander('Advanced iterative-ensemble settings', expanded=False):
        for field in ITER_ENS_FIELDS:
            if not (field['advanced'] and _iter_ens_visible(field)):
                continue
            if (field['key'] == 'oof_engine' and not ITER_ENS_SHOW_OOF_ENGINE
                    and st.session_state.get('iter_ens_oof_engine', 'runner') == 'runner'):
                continue
            _render_iter_ens_field(field)
    n_bio = sum(1 for m in models
                if m == 'GAT_biological_prior_knowledge'
                or m.startswith('GAT_biological_prior_knowledge_'))
    cfg = resolve_iter_ens()
    expected, maximum = _pipeline_utils.iter_ens_fit_estimate(cfg, len(models), n_bio)
    if two_phase:
        waves = _pipeline_utils.iter_ens_wave_groups(cfg, len(models), len(models) - n_bio,
                                                     oof_possible=(n_bio == 0))
        caption = (f"Expected extra model fits per task: {expected} (all of them are run; at most "
                   f"{maximum}) in {len(waves)} parallel wave(s); refits skip explainability.")
        if n_bio:
            caption += (" A bio-prior model cannot be fitted out of fold, so with one selected the "
                        "model weights come from the validation rows and phase 1 is skipped.")
        st.caption(caption)
    else:
        st.caption(f"Expected extra model fits per task: \u2248 {expected} (at most {maximum}); "
                   f"refits skip explainability.")


